export function planExport(keys, ctx, stamp) {
  const jobs = [];
  for (const opt of MED_EXPORT_OPTIONS.filter((o) => (keys || []).includes(o.key))) {
    const ext = opt.type === 'png' ? 'png' : opt.type === 'json' ? 'json' : 'xlsx';
