    /** 下载模板：表结构由 medSheetSpec 声明，这里只负责写出 */
    async downloadTemplate() {
      try {
        await writeWorkbook(await this.xlsxLib(), medTemplateSheets(), `PERMANOVA-med 模板_${this.stamp()}.xlsx`);
        this.$message.success('模板下载成功');
      } catch (e) {
