```
Wait: `writeWorkbook(XLSX, sheets, filename)` takes sheets as array of [name, aoa] pairs (from `for (const [name, aoa] of sheets)`). medTemplateSheets returns exactly `[['Outcome', aoa], ...]` ✓. PERMANOVA.vue calls `writeWorkbook(await this.xlsx(), pmTemplateSheets().map(([name, aoa]) => ({ name, aoa })), ...)` — hmm! PERMANOVA's pmTemplateSheets returns [{name, aoa}] presumably. Med's returns pairs. So for Med I pass medTemplateSheets() directly. ✓ (writeWorkbook destructures arrays).

The old filename was `PERMANOVA-med 模板_${timestamp}.xlsx` — preserve exactly ✓.

Block B (1028..1153) → openImport/handleFileChange/applyImport:
```js
    openImport() {
      this.importTabs = null;
      this.importFields = null;
      this.importIds = null;
      this.importError = '';
      this.importWarnings = [];
      this.showImportDialog = true;
    },

    /**
     * 四张表交给 mapWorkbook 按声明解析：表名走中英文别名、缺必需表指名拒绝，
     * 并且一律按「结局 Y」的样本 ID 对齐重排。
     * 以前这里按 Sheets['Outcome'] 精确取表、按行号配对：中介分析里 Y 与 M 错一行
     * 等于拿别人的中介去解释结局，模型照跑、图照画、系数全废。
     */
    async handleFileChange(file) {
      this.importError = '';
      this.importWarnings = [];
      this.importTabs = null;
      this.importFields = null;
      this.importIds = null;
      let sheets;
      try {
        sheets = await readWorkbook(file);
      } catch (e) {
        this.importError = '这个文件读不出来：' + (e.message || e) + '（要 .xlsx / .xls / .csv）';
        return;
      }
      const res = mapWorkbook(sheets, MED_IMPORT_SHEETS, { primary: 'outcome' });
      this.importWarnings = res.warnings || [];
      if (!res.ok) {
        this.importError = res.error;
        return;
      }
      this.importWarnings = this.importWarnings.concat(medWarnings(res.fields, res.ids));
      this.importFields = res.fields;
      this.importIds = res.ids;
      this.importTabs = previewFromFields(res.ids, res.fields.outcome, res.fields, {
        matrixKeys: [['outcome', '结局 Y'], ['mediator', '中介 M'], ['predictor', '暴露 X'], ['covariates', '协变量 Z']]
      });
    },

    /** 先看后填：用户点头才动表单 */
    applyImport() {
      if (!this.importFields) {
        // 已经报过的错优先（"缺哪张表"比"先选一个文件"有用得多）
        if (!this.importError) this.importError = '先选一个文件';
        return;
      }
      const patch = medToFormPatch(this.importFields, this.importIds);
      Object.assign(this.permanovaMedParams, patch);
      // 校验顺序照数据模板：先中介（定义 mediatorN），再 X / Y / Z，避免行列字典歧义
      this.validateMediatorData();
      this.validatePredictorData();
      this.validateOutcomeData();
      this.validateCovariates();
      this.showImportDialog = false;
      this.$message.success({
        message: `已填入 ${this.importIds.length} 个样本（按结局 Y 的样本顺序对齐）`,
        duration: 2500
      });
    },
