import fs from 'fs'; import path from 'path';
import { fileURLToPath, pathToFileURL } from 'url';
const ROOT = 'C:/Custom/CodeRepository/Demo/electron-egg', FRONTEND = path.join(ROOT, 'frontend');
const { createServer } = await import(pathToFileURL(path.join(FRONTEND, 'node_modules/vite/dist/node/index.js')).href);
const server = await createServer({ root: FRONTEND, configFile: path.join(FRONTEND, 'vite.config.js'), server: { middlewareMode: true }, appType: 'custom', logLevel: 'error' });
const df = path.join(FRONTEND, '.probe-deps.js');
fs.writeFileSync(df, ["export { createSSRApp, h } from 'vue';", "export { renderToString } from '@vue/server-renderer';", "export { default as ElementPlus } from 'element-plus';"].join('\n') + '\n');
const deps = await server.ssrLoadModule('/.probe-deps.js');
const h = deps.h;
const DialogStub = {
  name: 'ElDialog', props: { title: String, modelValue: Boolean, width: String },
  setup(props, { slots }) {
    return () => (props.modelValue ? h('div', { class: 'dialog-stub' }, [h('h4', props.title || ''), slots.default ? slots.default() : null, slots.footer ? slots.footer() : null]) : null);
  }
};
const UploadStub = { name: 'ElUpload', props: { drag: Boolean, accept: String }, setup(p, { slots }) { return () => h('div', { class: 'upload-stub' }, [slots.default ? slots.default() : null]); } };
for (const v of ['/src/views/r-analysis/PERMANOVA.vue', '/src/views/r-analysis/PERMANOVA_Med.vue']) {
  const comp = (await server.ssrLoadModule(v)).default;
  const app = deps.createSSRApp(comp);
  app.config.globalProperties.$message = Object.assign(() => {}, { success: () => {}, error: () => {}, warning: () => {}, info: () => {} });
  app.config.globalProperties.$router = { push() {} };
  app.component('ElDialog', DialogStub);
  app.component('ElUpload', UploadStub);
  app.use(deps.ElementPlus);
  const warns = [];
  app.config.warnHandler = (msg) => warns.push(String(msg).slice(0, 140));
  let html = '', err = null;
  try { html = await deps.renderToString(app); } catch (e) { err = e.message; }
  console.log('\n### ' + path.basename(v) + (err ? '  RENDER ERR: ' + err : ''));
  console.log('  warn 数:', warns.length, warns.slice(0, 4).map(w => '\n    - ' + w).join(''));
  console.log('  toolbar-content 包住了外壳:', /toolbar-content[^>]*>\s*<div class="toolbar-actions"/.test(html.replace(/\s+/g, ' ').replace(/data-v-[0-9a-f]+/g, '')));
}
fs.unlinkSync(df); await server.close();

