/** 用给定状态渲染整页；dataOverride 深合并到组件 data() 结果上 */
const render = async (tag, dataOverride) => {
  warnings.length = 0;
  const Wrapped = {
    ...Comp,
    data() {
      const d = Comp.data.call(this);
      return { ...d, ...dataOverride(d) };
    }
  };
  const app = vue.createSSRApp(Wrapped);
  app.use(ElementPlus);
