/** JSON 字符串 -> inspectValue */
export function inspectMatrix(str, refN = null) {
  let data;
  try {
    data = JSON.parse(str);
  } catch (e) {
    return { ok: false, error: 'JSON 格式错误：' + e.message };
  }
  return inspectValue(data, refN);
}

