// 造一个「能真跑」的 PERMANOVA-med 模板示例：10 样本 × (Y3 / M4 / X1 / Z2)
// 目标：下载模板 → 导入 → 点运行，必须成功且中介显著（否则用户第一次接触就是死路）
import fs from 'fs';
import os from 'os';
import path from 'path';
import { execFileSync } from 'child_process';

const ROOT = 'C:/Custom/CodeRepository/Demo/electron-egg';
const RSCRIPT = path.join(ROOT, 'r-portable', 'bin', 'Rscript.exe');

// 确定性伪随机（mulberry32），每次生成完全一样的数
let seed = 20260214;
const rnd = () => {
  seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
  let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
};
const nrm = () => {
  const a = rnd(), b = rnd();
  return Math.sqrt(-2 * Math.log(Math.max(1e-9, a))) * Math.cos(2 * Math.PI * b);
};
const r3 = (v) => Number(Math.max(0.01, v).toFixed(3));

const n = 10;
const X = Array.from({ length: n }, (_, i) => (i < 5 ? 1 : 0));
const Age = [34, 41, 29, 52, 38, 45, 31, 49, 36, 43];
const BMI = [22.4, 25.1, 21.8, 27.3, 23.9, 26.2, 22.1, 24.7, 25.8, 23.2];

const M = [
  [], [], [], []
];
const Y = [
  [], [], []
];
for (let i = 0; i < n; i++) {
  const x = X[i];
  const m1 = r3(4.2 + 3.0 * x + 0.55 * nrm());
  const m2 = r3(9.5 - 3.0 * x + 0.55 * nrm());
  const m3 = r3(5.4 + 1.6 * x + 0.5 * nrm());
  const m4 = r3(2.8 + 0.0 * x + 0.7 * nrm());
  M[0].push(m1); M[1].push(m2); M[2].push(m3); M[3].push(m4);
  Y[0].push(r3(0.9 * m1 + 0.35 * nrm()));
  Y[1].push(r3(0.75 * m2 + 0.35 * nrm()));
  Y[2].push(r3(3.1 + 0.4 * nrm()));
}
const row = (arr, i) => [arr[i]];

const aoaY = [['样本 ID', 'Y1', 'Y2', 'Y3'], ...Y.transpose ? [] : Array.from({ length: n }, (_, i) => [`Sample${i + 1}`, Y[0][i], Y[1][i], Y[2][i]])];
const aoaM = [['样本 ID', 'M1', 'M2', 'M3', 'M4'], ...Array.from({ length: n }, (_, i) => [`Sample${i + 1}`, M[0][i], M[1][i], M[2][i], M[3][i]])];
const aoaX = [['样本 ID', 'X1'], ...Array.from({ length: n }, (_, i) => [`Sample${i + 1}`, X[i]])];
const aoaZ = [['样本 ID', 'Age', 'BMI'], ...Array.from({ length: n }, (_, i) => [`Sample${i + 1}`, Age[i], BMI[i]])];

// 送 R：行字典（与导入后表单里的形状一致）
const dict = (cols, names) => {
  const o = {};
  for (let i = 0; i < n; i++) o[`Sample${i + 1}`] = cols.map((c) => c[i]);
  return o;
};
const payload = {
  outcomeData: dict(Y), mediatorData: dict(M), predictorData: dict(X), covariates: dict2(Age, BMI), permutations: 100, seed: 7
};
function dict2(a, b) {
  const o = {};
  for (let i = 0; i < n; i++) o[`Sample${i + 1}`] = [a[i], b[i]];
  return o;
}

const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'medtpl-'));
const inp = path.join(tmp, 'in.json'), outp = path.join(tmp, 'out.json');
fs.writeFileSync(inp, JSON.stringify(payload));
const err = path.join(tmp, 'e.txt');
