if (!res.success) console.log('错误：', res.error, fs.readFileSync(err, 'utf8').slice(0, 800));

const lit = (a) => a.map((r) => '      [' + r.map((v) => (typeof v === 'string' ? `'${v}'` : v)).join(', ') + ']').join(',\n');
