  seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
  let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
};
const nrm = () => {
  const a = rnd(), b = rnd();
  return Math.sqrt(-2 * Math.log(Math.max(1e-9, a))) * Math.cos(2 * Math.PI * b);
};
const r3 = (v) => Number(Math.max(0.05, v).toFixed(3));

const X = Array.from({ length: n }, (_, i) => (i < Math.ceil(n / 2) ? 1 : 0));
const Age = Array.from({ length: n }, (_, i) => [34, 41, 29, 52, 38, 45, 31, 49, 36, 43][i % 10]);
const BMI = Array.from({ length: n }, (_, i) => [22.4, 25.1, 21.8, 27.3, 23.9, 26.2, 22.1, 24.7, 25.8, 23.2][i % 10]);

const coefX = cfg.coefX ?? 3.0;   // X -> M
const yOnM = cfg.yOnM ?? 0.9;     // M -> Y
const noiseM = cfg.noiseM ?? 0.55;
const noiseY = cfg.noiseY ?? 0.35;

const M = [[], [], [], []];
const Y = [[], [], []];
for (let i = 0; i < n; i++) {
  const x = X[i];
  const m1 = r3(4.2 + coefX * x + noiseM * nrm());
  const m2 = r3(9.5 - coefX * x + noiseM * nrm());
  const m3 = r3(5.4 + (coefX / 2) * x + noiseM * nrm());
  const m4 = r3(2.8 + 0.7 * nrm());
  M[0].push(m1); M[1].push(m2); M[2].push(m3); M[3].push(m4);
  Y[0].push(r3(yOnM * m1 + noiseY * nrm()));
  Y[1].push(r3(yOnM * 0.8 * m2 + noiseY * nrm()));
  Y[2].push(r3(3.1 + 0.4 * nrm()));
}
const at = (i) => `Sample${i + 1}`;
const aoa = (head, cols) => [
  ['样本 ID', ...head],
  ...Array.from({ length: n }, (_, i) => [at(i), ...cols.map((c) => c[i])])
];
const dict = (cols) => {
  const o = {};
  for (let i = 0; i < n; i++) o[at(i)] = cols.map((c) => c[i]);
  return o;
};

fs.writeFileSync(inp, JSON.stringify({
  outcomeData: dict(Y), mediatorData: dict(M), predictorData: dict(X.map((v) => [v])),
  covariates: dict([Age, BMI]), permutations: cfg.perm ?? 100, seed: 7
}));
let res;
try {
  execFileSync(RSCRIPT, [path.join(ROOT, 'r-scripts/permanova_med.R'), inp, outp, err], { cwd: ROOT, stdio: 'ignore', timeout: 300000 });
  res = JSON.parse(fs.readFileSync(outp, 'utf8'));
} catch (e) {
  console.log('R 退出码', e.status, '\n', fs.readFileSync(err, 'utf8').slice(0, 1200));
  process.exit(1);
}
console.log(JSON.stringify({
  cfg, success: res.success, p: res.mediation_p, nperm: res.n_perm_used,
  tests: (res.covariate_tests || []).map((t) => `${t.label}:F=${t.F_statistic?.toFixed(2)},p=${t.p_value}`),
  error: res.error || null
}));

const lit = (a) => a.map((r) => "        [" + r.map((v) => (typeof v === 'string' ? `'${v}'` : String(v))) + "]".replace(']', ']')).join(',\n');
const fmt = (a) => a.map((r) => '        [' + r.map((v) => (typeof v === 'string' ? `'${v}'` : String(v))).join(', ') + ']').join(',\n');
if (res.success) {
  console.log('\n=== 可粘贴 ===');
  console.log(`['Outcome', [\n${fmt(aoa(['Y1', 'Y2', 'Y3'], Y))}\n      ]],`);
  console.log(`['Mediator', [\n${fmt(aoa(['M1', 'M2', 'M3', 'M4'], M))}\n      ]],`);
  console.log(`['Predictor', [\n${fmt(aoa(['X1'], X.map((v) => [v])))}\n      ]],`);
  console.log(`['Covariates', [\n${fmt(aoa(['Age', 'BMI'], [Age, BMI]))}\n      ]],`);
}

