const errFile = path.join(tmp, 'last.err');

let seed = 987654321;
const rnd = () => {
  seed = (seed * 1103515245 + 12345) & 0x7fffffff;
  return seed / 0x7fffffff;
};
const r3 = (v) => Number(Math.max(0.05, v).toFixed(3));

const mk = (n, taxa, p) => {
  const X = Array.from({ length: n }, (_, i) => (i < Math.ceil(n / 2) ? 1 : 0));
  const M = Array.from({ length: n }, (_, i) =>
    Array.from({ length: taxa }, (_, k) => r3((k % 2 ? 9 : 4) + (k % 2 ? -2.5 : 2.5) * X[i] + rnd())));
  const Y = Array.from({ length: n }, (_, i) =>
    Array.from({ length: 3 }, (_, k) => r3(0.8 * M[i][k % taxa] + rnd() * 0.4)));
  const dict = (cols) => {
    const o = {};
    for (let i = 0; i < n; i++) o[`S${i + 1}`] = cols[i];
    return o;
  };
  return { outcomeData: dict(Y), mediatorData: dict(M), predictorData: dict(X.map((v) => [v])), permutations: p, seed: 7 };
};

const rows = [];
for (const p of [100, 1000]) {
  for (const n of [4, 6, 8, 10, 12, 14, 16, 20, 24, 30, 36]) {
    const inp = path.join(tmp, `in-${n}-${p}.json`);
