      execFileSync(RSCRIPT, [path.join(ROOT, 'r-scripts/permanova_med.R'), inp, outp, e],
        { cwd: ROOT, stdio: ['ignore', 'pipe', 'pipe'], timeout: 300000 });
      const res = JSON.parse(fs.readFileSync(outp, 'utf8'));
      pv = `p=${res.mediation_p} nperm=${res.n_perm_used}`;
    } catch (ex) {
      status = 'FAIL';
      const txt = fs.existsSync(e) ? fs.readFileSync(e, 'utf8') : '';
      const m = /permanovaFL 错误:\s*(.+)/.exec(txt) || /Error:\s*(.+)/.exec(txt);
      msg = (m ? m[1] : ex.message).trim().slice(0, 60);
    }
    rows.push(`n=${String(n).padStart(2)} perm=${String(p).padStart(4)} ${status.padEnd(4)} ${pv.padEnd(20)} ${msg}`);
    console.log(rows[rows.length - 1]);
  }
}
fs.writeFileSync(errFile, '');

