// 扫出 LDM permanovaFL 的真实可用下限：n（样本数）× 有无协变量 Z × 置换次数
import fs from 'fs';
import os from 'os';
import path from 'path';
import { execFileSync } from 'child_process';

const ROOT = 'C:/Custom/CodeRepository/Demo/electron-egg';
const RSCRIPT = path.join(ROOT, 'r-portable', 'bin', 'Rscript.exe');
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'ldmsweep-'));

let seed = 987654321;
const rnd = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };
const r3 = (v) => Number(Math.max(0.05, v).toFixed(3));

const mk = (n, withZ, p) => {
  const X = Array.from({ length: n }, (_, i) => (i < Math.ceil(n / 2) ? 1 : 0));
  const M = Array.from({ length: n }, (_, i) =>
    Array.from({ length: 4 }, (_, k) => r3((k % 2 ? 9 : 4) + (k % 2 ? -2.5 : 2.5) * X[i] + rnd())));
  const Y = Array.from({ length: n }, (_, i) =>
    Array.from({ length: 3 }, (_, k) => r3(0.8 * M[i][k % 4] + rnd() * 0.4)));
  const Z = Array.from({ length: n }, (_, i) => [Number((20 + i * 1.7 + rnd()).toFixed(2)), Number((60 + (i % 5) * 4 + rnd()).toFixed(2))]);
  const dict = (rows) => { const o = {}; for (let i = 0; i < n; i++) o[`S${i + 1}`] = rows[i]; return o; };
  const out = {
    outcomeData: dict(Y), mediatorData: dict(M), predictorData: dict(X.map((v) => [v])),
    permutations: p, seed: 7
  };
  if (withZ) out.covariates = dict(Z);
  return out;
};

const out = [];
for (const withZ of [true, false]) {
  for (const p of [100, 1000]) {
    for (const n of [4, 5, 6, 7, 8, 9, 10, 12, 15, 20]) {
      const inp = path.join(tmp, `in-${withZ ? 'Z' : 'nz'}-${p}-${n}.json`);
      const o = inp + '.out', e = inp + '.err';
      fs.writeFileSync(inp, JSON.stringify(mk(n, withZ, p)));
      let status = 'ok', msg = '', pv = '';
      try {
        execFileSync(RSCRIPT, [path.join(ROOT, 'r-scripts/permanova_med.R'), inp, o, e],
          { cwd: ROOT, stdio: ['ignore', 'pipe', 'pipe'], timeout: 300000 });
        const res = JSON.parse(fs.readFileSync(o, 'utf8'));
        pv = `p=${res.mediation_p} nperm=${res.n_perm_used}`;
      } catch (ex) {
        status = 'FAIL';
        const txt = [ex.stdout, ex.stderr, fs.existsSync(e) ? fs.readFileSync(e, 'utf8') : ''].filter(Boolean).join('\n');
        const m = /permanovaFL 错误:\s*(.+)/.exec(txt) || /Error:\s*(.+)/.exec(txt);
        msg = (m ? m[1] : '未知').trim().slice(0, 46);
      }
      const line = `Z=${withZ ? '有' : '无'} perm=${String(p).padStart(4)} n=${String(n).padStart(2)} ${status.padEnd(4)} ${pv.padEnd(22)} ${msg}`;
      console.log(line);
      out.push(line);
    }
  }
}
fs.writeFileSync(path.join(tmp, 'all.txt'), out.join('\n'));

