// 生成可直接粘进 medSheetSpec.js 的「能真跑通」模板数据（10 样本 × Y3/M4/X1/Z2）
import fs from 'fs';
import os from 'os';
import path from 'path';
import { execFileSync } from 'child_process';

const ROOT = 'C:/Custom/CodeRepository/Demo/electron-egg';
const RSCRIPT = path.join(ROOT, 'r-portable', 'bin', 'Rscript.exe');
const N = 10;

let seed = 20260214;
const rnd = () => {
  seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
  let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
};
const nrm = () => {
  const a = Math.max(1e-9, rnd()), b = rnd();
  return Math.sqrt(-2 * Math.log(a)) * Math.cos(2 * Math.PI * b);
};
const r2 = (v) => Number(Math.max(0.05, v).toFixed(2));

// X：前 5 个 = 1（暴露），后 5 个 = 0
const X = Array.from({ length: N }, (_, i) => (i < 5 ? 1 : 0));
// M：M1/M3 随 X 上升，M2 随 X 下降，M4 是背景噪声
const M = Array.from({ length: N }, (_, i) => [
  r2(4.2 + 3.0 * X[i] + 0.55 * nrm()),
  r2(9.5 - 3.0 * X[i] + 0.55 * nrm()),
  r2(5.4 + 1.5 * X[i] + 0.5 * nrm()),
  r2(2.8 + 0.7 * nrm())
]);
// Y：Y1/Y2 由中介驱动（真正的中介通路），Y3 与 X/M 都无关
const Y = Array.from({ length: N }, (_, i) => [
  r2(0.9 * M[i][0] + 0.35 * nrm()),
  r2(0.75 * M[i][1] + 0.35 * nrm()),
  r2(3.1 + 0.4 * nrm())
]);
// Z：与 X/M/Y 都无关的纯协变量（模板只演示形状，不想暗示因果结论）
const Z = Array.from({ length: N }, (_, i) => [
  Number((28 + i * 2 + (i % 3)).toFixed(0)),
  r2(21.5 + (i % 4) * 1.6 + 0.5 * nrm())
]);

const ids = Array.from({ length: N }, (_, i) => `Sample${i + 1}`);
const aoa = (head, rows) => [['样本 ID', ...head], ...rows.map((r, i) => [ids[i], ...r])];
const aoaX = [['样本 ID', 'X1'], ...X.map((v, i) => [ids[i], v])];

const dict = (rows) => { const o = {}; rows.forEach((r, i) => { o[ids[i]] = r; }); return o; };
const payload = {
  outcomeData: dict(Y), mediatorData: dict(M), predictorData: dict(X.map((v) => [v])),
  covariates: dict(Z), permutations: 100, seed: 7
};

const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'medtpl-'));
const inp = path.join(tmp, 'in.json'), outp = inp + '.out', err = inp + '.err';
fs.writeFileSync(inp, JSON.stringify(payload));
try {
  execFileSync(RSCRIPT, [path.join(ROOT, 'r-scripts/permanova_med.R'), inp, outp, err],
    { cwd: ROOT, stdio: ['ignore', 'pipe', 'pipe'], timeout: 300000 });
} catch (e) {
  console.log('R 失败:\n', String(e.stdout || '') + String(e.stderr || '') + fs.readFileSync(err, 'utf8'));
  process.exit(1);
}
const res = JSON.parse(fs.readFileSync(outp, 'utf8'));
console.log(JSON.stringify({
  success: res.success, p: res.mediation_p, nperm: res.n_perm_used,
  Z: res.model_info?.confounder_vars, tests: (res.covariate_tests || []).map((t) => `${t.label} F=${t.F_statistic} p=${t.p_value}`)
}));

const fmt = (a) => a.map((r) => '        [' + r.map((v) => (typeof v === 'string' ? `'${v}'` : v)).join(', ') + ']').join(',\n');
const sheet = (name, rows) => `    ['${name}', [\n${fmt(rows)}\n    ]]`;
console.log('\n=== 粘贴块 ===');
console.log([
  sheet('Outcome', aoa(['Y1', 'Y2', 'Y3'], Y)),
  sheet('Mediator', aoa(['M1', 'M2', 'M3', 'M4'], M)),
  sheet('Predictor', aoaX),
  sheet('Covariates', aoa(['Age', 'BMI'], Z))
].join(',\n') + ',');

