// 把生成好的 20 样本模板数据写进 medSheetSpec.js 的 medTemplateSheets()
import { execFileSync } from 'child_process';
import fs from 'fs';

const SPEC = 'C:/Custom/CodeRepository/Demo/electron-egg/frontend/src/utils/medSheetSpec.js';
const gen = execFileSync('node', ['C:/Users/uf107146/AppData/Local/Temp/gen_tpl3.mjs'], {
  cwd: 'C:/Custom/CodeRepository/Demo/electron-egg', maxBuffer: 1 << 24
}).toString();
const head = /"success":(true|false)/.exec(gen);
if (!head || head[1] !== 'true') { console.error('生成数据没跑通，拒绝写入'); process.exit(1); }
const blockStart = gen.indexOf('=== 粘贴块 ===');
const dataBlock = gen.slice(blockStart).replace(/^=== 粘贴块 ===\r?\n/, '').trimEnd().replace(/,$/, '');
console.log('数据块行数:', dataBlock.split(/\r?\n/).length);

const notes = `    ['填写说明', [
      ['PERMANOVA-med 模板填写说明'],
      [''],
      ['四张表的样本 ID 必须一致（表名可写中文：结局Y / 中介M / 暴露X / 协变量Z）。'],
      ['样本数据可以按任意顺序排列，程序会按样本 ID 对齐；缺样本会拒绝导入。'],
      ['Outcome / Mediator 必须是数值；Predictor / Covariates 可以是分组文本。'],
      [''],
      ['样本数：至少 6 个（LDM 实测下限，n<=4 直接崩、n=5 会随机崩），建议 20 个以上。'],
      ['本示例的 20 个样本是「下载模板 → 导入 → 运行」实测跑通过的（中介 p<0.05），可以直接点运行。'],
      ['连续变量请带小数（如年龄写 28.3）或先分成少数几档。'],
      ['   逐行写成 28/29/30… 这种整数值会被当成多水平因子，自由度被吃光后 LDM 会失败。'],
      ['置换次数需要是 100 的整数倍（LDM 内部按 100 一块分批，不是整数倍会数组越界）。']
    ]]`;

const body = `export function medTemplateSheets() {
  return [
${dataBlock},
${notes}
  ];
}`;

let s = fs.readFileSync(SPEC, 'utf8');
const start = s.indexOf('export function medTemplateSheets() {');
if (start < 0) { console.error('找不到 medTemplateSheets'); process.exit(1); }
const after = s.slice(start);
const endRel = after.indexOf('\n}');
if (endRel < 0) { console.error('找不到函数结尾'); process.exit(1); }
const oldFn = after.slice(0, endRel + 2);
if (!oldFn.includes("['Outcome', [") || !oldFn.includes('填写说明')) {
  console.error('旧函数形状不符合预期，拒绝替换:\n' + oldFn.slice(0, 200)); process.exit(1);
}
s = s.slice(0, start) + body + s.slice(start + oldFn.length);
// 顶部注释也要跟着改口径
s = s.replace('/** 下载模板：表名与示例逐字保留（用户手头的文件靠这些名字） */',
  '/**\n * 下载模板：表名与示例数据。\n * 这份示例不只是格式说明——用户会真的导入它并点运行，所以必须能跑通：\n * 20 样本、协变量带小数（避免被当成多水平因子吃掉自由度）。\n * 实测（便携版 R + permanova_med.R, permutations=100）：success=true、中介 p<0.05。\n */');
fs.writeFileSync(SPEC, s);
console.log('medTemplateSheets 已替换为新数据；文件行数', s.split(/\r?\n/).length);

