// 造一个「下载模板 → 导入 → 运行」真能跑出显著结果的 PERMANOVA 模板
// 思路：先造 8 样本 × 6 物种的群落数据（两组真的分开），用 vegan::vegdist 算 Bray-Curtis，
// 四舍五入到 2 位写进示例矩阵；再用真实的导入链 + permanova.R 验一遍。
import fs from 'fs';
import os from 'os';
import path from 'path';
import { execFileSync } from 'child_process';

const ROOT = 'C:/Custom/CodeRepository/Demo/electron-egg';
const RSCRIPT = path.join(ROOT, 'r-portable', 'bin', 'Rscript.exe');
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'pmtpl-'));

const N = 8;
let seed = 4242;
const rnd = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };
const ids = Array.from({ length: N }, (_, i) => `Sample${i + 1}`);
const group = Array.from({ length: N }, (_, i) => (i < 4 ? 'Control' : 'Treatment'));
// 两组各自主导不同的菌（A 组前 3 个高，B 组后 3 个高）+ 小噪声
const species = ['Bacteroides', 'Prevotella', 'Faecalibacterium', 'Ruminococcus', 'Akkermansia', 'Bifidobacterium'];
const comm = Array.from({ length: N }, (_, i) => {
  const a = group[i] === 'Control';
  return [
    Math.round((a ? 45 : 9) + rnd() * 4),
    Math.round((a ? 38 : 7) + rnd() * 4),
    Math.round((a ? 30 : 6) + rnd() * 4),
    Math.round((a ? 6 : 41) + rnd() * 4),
    Math.round((a ? 4 : 33) + rnd() * 4),
    Math.round((a ? 3 : 27) + rnd() * 4)
  ];
});
// 年龄/BMI 都带小数，避免被当离散分组
const age = Array.from({ length: N }, (_, i) => Number((31 + i * 2.3 + rnd()).toFixed(1)));
const bmi = Array.from({ length: N }, (_, i) => Number((22.4 + (i % 4) * 1.3 + rnd()).toFixed(1)));

// 用 R 算 Bray-Curtis 距离矩阵
const csv = path.join(tmp, 'comm.csv');
fs.writeFileSync(csv, [species.join(','), ...comm.map((r) => r.join(','))].join('\n'));
const rout = path.join(tmp, 'dist.txt');
execFileSync(RSCRIPT, ['-e', `
suppressPackageStartupMessages(library(vegan))
x <- as.matrix(read.csv("${csv.replace(/\\/g, '/')}", row.names = 1))
d <- round(as.matrix(vegdist(x, method = "bray")), 2)
write.csv(format(d, nsmall = 2, trim = TRUE), "${rout.replace(/\\/g, '/')}", row.names = FALSE, quote = FALSE)
`], { stdio: 'inherit' });
const rows = fs.readFileSync(rout, 'utf8').split(/\r?\n/).filter((l) => l.trim()).slice(1, N + 1)
  .map((l) => l.split(',').map((v) => Number(String(v).trim())));
const dist = Array.from({ length: N }, (_, i) => rows.map((r) => r[i]));   // 读回来转置修正（write.csv 列序）
const use = dist.every((r) => r.length === N) ? dist : rows;

// 组成模板表
const aoaDist = [['样本', ...ids], ...ids.map((id, i) => [id, ...use[i]])];
const aoaSample = [['样本', 'Group', 'Age', 'BMI'], ...ids.map((id, i) => [id, group[i], age[i], bmi[i]])];
const aoaFormula = [
  ['模型公式'], ['Y ~ Group + Age + BMI'], [''],
  ['公式说明：'], ['~ 左边是因变量（写成 Y 即可，程序用距离矩阵代替它）。'],
  ['Group 是待检验分组；Age / BMI 作为连续协变量扣除。']
];

// 走真实链路：写 xlsx -> readWorkbook -> mapWorkbook -> pmToFormPatch -> 送 R
const payload = {
  distanceMatrix: use,
  permutations: 999,
  seed: 7,
  sampleData: ids.map((id, i) => ({ 样本: id, Group: group[i], Age: age[i], BMI: bmi[i] })),
  formula: 'Y ~ Group + Age + BMI'
};
const inp = path.join(tmp, 'in.json'), outp = inp + '.out', err = inp + '.err';
fs.writeFileSync(inp, JSON.stringify(payload));
try {
  execFileSync(RSCRIPT, [path.join(ROOT, 'r-scripts/permanova.R'), inp, outp, err],
    { cwd: ROOT, stdio: ['ignore', 'pipe', 'pipe'], timeout: 300000 });
} catch (e) {
  console.log('R 失败:', String(e.stdout || ''), String(e.stderr || ''), fs.readFileSync(err, 'utf8'));
  process.exit(1);
}
const res = JSON.parse(fs.readFileSync(outp, 'utf8'));
const model = (res.permanova_result || []).find((r) => r._row === 'Model');
console.log('p =', res.p_value ?? (model && model.p_value), '| F =', model && model.F_model, '| R2 =', model && model.R2);

const q = (v) => typeof v === 'string' ? `'${v}'` : v;
const line = (r) => '      [' + r.map(q).join(', ') + ']';
console.log('\n=== 粘贴块 ===');
console.log(`    ['距离矩阵', [\n${[aoaDist[0], ...aoaDist.slice(1)].map(line).join(',\n')}\n    ]],`);
console.log(`    ['样本数据', [\n${[aoaSample[0], ...aoaSample.slice(1)].map(line).join(',\n')}\n    ]],`);
console.log(`    ['模型公式', [\n${aoaFormula.map((r) => '      ' + JSON.stringify(r.map(q).replace(/"/g, "'"))).join(',\n')}\n    ]],`);

