// 造一个「下载模板 → 导入 → 运行」真能跑出显著结果的 Non-random PERMANOVA 示例
// 设计：3 个批次（strata）× 每批 2 样本（Case/Control 各一）
//   - group 效应真实且**在每个批次内部都成立** → p_constrained 显著
//   - 批次本身有整体偏移（BC 响应在 B2/B3 更高）→ 提醒用户 p_free 与 p_constrained 的差别从哪来
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { execFileSync } from 'node:child_process';

const ROOT = 'C:/Custom/CodeRepository/Demo/electron-egg';
const RSCRIPT = path.join(ROOT, 'r-portable/bin/Rscript.exe');
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'nrtpl-'));

const species = ['Bacteroides', 'Prevotella', 'Faecalibacterium', 'Ruminococcus', 'Akkermansia', 'Bifidobacterium'];
const rows = [];
const meta = [];
const coord = [];
let seed = 777;
const rnd = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff - 0.5; };

for (let b = 0; b < 3; b++) {
  const shift = b * 4;                       // 批次整体偏移（BC 响应随批次升高）
  for (const g of ['Case', 'Control']) {
    const caseLike = g === 'Case';
    rows.push([
      Math.round(28 + shift + (caseLike ? 16 : -14) + rnd() * 3),   // Bacteroides
      Math.round(14 + shift + (caseLike ? -8 : 10) + rnd() * 3),    // Prevotella
      Math.round(18 + (caseLike ? 9 : -6) + rnd() * 3),             // Faecalibacterium
      Math.round(10 + shift + (caseLike ? -5 : 8) + rnd() * 3),     // Ruminococcus
      Math.round(6 + (caseLike ? 7 : -3) + rnd() * 2),              // Akkermansia
      Math.round(9 + (caseLike ? -4 : 5) + rnd() * 2)               // Bifidobacterium
    ]);
    meta.push([`S${b * 2 + (g === 'Case' ? 1 : 2)}`, g, `B${b + 1}`]);
    // 空间坐标：同一个批次聚成一团（给 spatial 方案留个能用的例子）
    coord.push([Number((b * 20 + rnd() * 2).toFixed(1)), Number(((g === 'Case' ? 0 : 6) + rnd() * 2).toFixed(1))]);
  }
}
const ids = meta.map((m) => m[0]);

const aoaCommunity = [['样本', ...species], ...rows.map((r, i) => [ids[i], ...r])];
const aoaSample = [['样本', 'group', 'strata'], ...meta];
const aoaCoord = [['样本', 'x', 'y'], ...ids.map((id, i) => [id, ...coord[i]])];

// 真跑：stratified（按 strata 受限置换）
const payload = {
  communityData: rows,
  sampleData: meta.map((m) => ({ sample: m[0], group: m[1], strata: m[2] })),
  coordinates: ids.map((id, i) => [id, ...coord[i]]),
  formula: 'group', scheme: 'stratified', strata: 'strata',
  distance: 'bray', permutations: 999, seed: 7
};
const inp = path.join(tmp, 'in.json'), outp = inp + '.out', err = inp + '.err';
fs.writeFileSync(inp, JSON.stringify(payload));
try {
  execFileSync(RSCRIPT, [path.join(ROOT, 'r-scripts/nonrandom_permanova.R'), inp, outp, err],
    { cwd: ROOT, stdio: ['ignore', 'pipe', 'pipe'], timeout: 300000 });
} catch (e) {
  console.log('R 失败:', String(e.stdout || '').slice(0, 300), fs.readFileSync(err, 'utf8').slice(0, 400));
  process.exit(1);
}
const r = JSON.parse(fs.readFileSync(outp, 'utf8'));
console.log('F=', r.observed.F_model, 'p_free=', r.observed.p_free, 'p_constrained=', r.observed.p_constrained,
  '| feasible_blocks=', r.permutation.feasible_blocks);

const line = (r) => '      [' + r.map((v) => (typeof v === 'string' ? `'${v}'` : v)).join(', ') + ']';
console.log('\n=== 粘贴块 ===');
console.log(`    ['物种矩阵', [\n${[aoaCommunity[0], ...aoaCommunity.slice(1)].map(line).join(',\n')}\n    ]],`);
console.log(`    ['样本信息', [\n${[aoaSample[0], ...aoaSample.slice(1)].map(line).join(',\n')}\n    ]],`);
console.log(`    ['坐标', [\n${[aoaCoord[0], ...aoaCoord.slice(1)].map(line).join(',\n')}\n    ]],`);

// Non-random PERMANOVA 的下载模板：12 样本 = 3 批次 × (2 Case + 2 Control)
// 为什么不能是 6 样本 / 每批 1:1 —— 层内只有 1 Case + 1 Control 时，
// 全局翻转标签得到的置换与观测设计完全同构，置换零分布退化，
// p 的下界约为 2/(2^3) = 0.25，无论效应多强都不可能显著（实测旧模板 p_free=1、p_constrained=1）。
// 每批 2:2 才有 C(4,2)^3 = 216 个置换（含全局翻转约 108 个等价类），p 下界约 0.009。
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { execFileSync } from 'node:child_process';

const ROOT = 'C:/Custom/CodeRepository/Demo/electron-egg';
const RSCRIPT = path.join(ROOT, 'r-portable/bin/Rscript.exe');
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'nrtpl-'));

const species = ['Bacteroides', 'Prevotella', 'Faecalibacterium', 'Ruminococcus', 'Akkermansia', 'Bifidobacterium'];
let seed = 31415;
const rnd = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff - 0.5; };

const rows = [], meta = [], coord = [];
for (let b = 0; b < 3; b++) {
  const shift = b * 5;                      // 批次整体偏移：让 strata 真的有力
  const layout = [['Case', 0], ['Case', 1], ['Control', 2], ['Control', 3]];
  for (const [g, k] of layout) {
    const caseLike = g === 'Case';
    rows.push([
      Math.round(26 + shift + (caseLike ? 15 : -12) + rnd() * 4),
      Math.round(15 + shift + (caseLike ? -9 : 11) + rnd() * 4),
      Math.round(19 + (caseLike ? 8 : -6) + rnd() * 4),
      Math.round(11 + shift + (caseLike ? -6 : 9) + rnd() * 4),
      Math.round(7 + (caseLike ? 6 : -4) + rnd() * 3),
      Math.round(9 + (caseLike ? -4 : 5) + rnd() * 3)
    ]);
    const id = `S${b * 4 + k + 1}`;
    meta.push([id, g, `B${b + 1}`]);
    coord.push([id, Number((b * 20 + k * 1.5 + rnd()).toFixed(1)), Number(((caseLike ? 0 : 7) + rnd()).toFixed(1))]);
  }
}
const ids = meta.map((m) => m[0]);

const payload = {
  communityData: rows,
  sampleData: meta.map((m) => ({ sample: m[0], group: m[1], strata: m[2] })),
  coordinates: coord,
  formula: 'group', scheme: 'stratified', strata: 'strata',
  distance: 'bray', permutations: 999, seed: 7
};
const inp = path.join(tmp, 'in.json'), outp = inp + '.out', err = inp + '.err';
fs.writeFileSync(inp, JSON.stringify(payload));
try {
  execFileSync(RSCRIPT, [path.join(ROOT, 'r-scripts/nonrandom_permanova.R'), inp, outp, err],
    { cwd: ROOT, stdio: ['ignore', 'pipe', 'pipe'], timeout: 300000 });
} catch (e) {
  console.log('R 失败:', String(e.stdout || '').slice(0, 300), fs.readFileSync(err, 'utf8').slice(0, 400));
  process.exit(1);
}
const r = JSON.parse(fs.readFileSync(outp, 'utf8'));
console.log('F=', r.observed.F_model, '| p_free=', r.observed.p_free, '| p_constrained=', r.observed.p_constrained,
  '| feasible_blocks=', r.permutation.feasible_blocks, '| performed=', r.permutation.performed);

const line = (r) => '      [' + r.map((v) => (typeof v === 'string' ? `'${v}'` : v)).join(', ') + ']';
const sheet = (n, aoa) => `    ['${n}', [\n${aoa.map(line).join(',\n')}\n    ]],`;
console.log('\n=== 粘贴块 ===');
console.log(sheet('物种矩阵', [['样本', ...species], ...rows.map((r, i) => [ids[i], ...r])]));
console.log(sheet('样本信息', [['样本', 'group', 'strata'], ...meta]));
console.log(sheet('坐标', [['样本', 'x', 'y'], ...coord]));

