  const ids = JSON.parse(vm.permanovaParams.distanceMatrixStr || '[]');
  check('模板至少 8 个样本（5 个时自由度太少，示例不好看结果）', ids.length >= 8, String(ids.length));
  check('距离矩阵对称、对角为 0',
