/**
 * 图表容器就绪等待（三个分析界面共用）
 * ---------------------------------------------------------------
 * 症状：「初次分析时图表没绘制，切换图表类型才画出来」。
 * 原因不是 ECharts，是时序：分析结果写进 data 的同一帧里，结果区（v-if）才刚要出现，
 * 视图紧接着在 $nextTick 里找 DOM。找不到时旧代码一律 `if (!el) return;` ——
 * **静默放弃**，之后再没有第二次机会，只有用户手动切 tab 才会重新调用渲染。
 *
 * 这里把「等一下再看一次」变成显式、有界、可测的行为：
 *   - 拿到容器：resolve({ el, waited })
 *   - 试满仍没有：resolve({ el: null, waited })，由调用方决定是提示还是沉默
 * 不用 requestAnimationFrame：$nextTick 在 Node（harness）里也能跑，rAF 不行。
 */

/**
 * @param {() => any} getHost       取 DOM 容器的函数（每轮重新取，别缓存）
 * @param {(cb: Function) => void} nextTick  Vue 的 this.$nextTick
 * @param {{ attempts?: number }} [opts]      最多重试几帧
 */
export function hostWhenReady(getHost, nextTick, opts = {}) {
  const attempts = opts.attempts ?? 3;
  let waited = 0;
  return new Promise((resolve) => {
    const step = () => {
      let el = null;
      try {
        el = getHost() || null;
      } catch (e) {
        el = null;                      // getHost 自己炸了也算「还没就绪」，不要连带把渲染链路打挂
      }
      if (el) return resolve({ el, waited });
      if (waited >= attempts) return resolve({ el: null, waited });
      waited += 1;
      nextTick(step);
    };
    step();
  });
}

/**
 * 三个视图共用的画图入口：等容器 -> 动态 import echarts -> setOption。
 * 抽出来的理由：三份 renderXxx 以前各写各的，同一个时序 bug 修了 A 忘了 B。
 *
 * @param {object} p
 * @param {() => any} p.getHost
 * @param {(cb: Function) => void} p.nextTick
 * @param {object} p.option        已经算好的 ECharts option
 * @param {(name: string) => Promise<any>} p.importEcharts  便于测试注入
 */
export async function drawWhenReady(p) {
  const { getHost, nextTick, option } = p;
  const importEcharts = p.importEcharts || (() => import('echarts'));
  const { el, waited } = await hostWhenReady(getHost, nextTick, p);
  if (!el) return { ok: false, reason: 'no-host', waited };
  if (!option) return { ok: false, reason: 'no-option', waited };
  const echarts = await importEcharts();
  const chart = echarts.getInstanceByDom(el) || echarts.init(el);
  chart.setOption(option, true);
  chart.resize();
  return { ok: true, waited };
}

