import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { pathToFileURL } from 'node:url';

const ROOT = 'C:/Custom/CodeRepository/Demo/electron-egg';
const { loadFrontendUtils } = await import(pathToFileURL(path.join(ROOT, 'r-scripts/tools/load_frontend_utils.mjs')).href);
const { nonrandomTemplates: nrt } = await loadFrontendUtils(['nonrandomTemplates']);
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'chk-'));

const ids = Object.keys(nrt.NR_TEMPLATE_MAP);
let warned = [];
for (const id of ids) {
  const d = nrt.buildNonrandomTemplateData(nrt.NR_TEMPLATE_MAP[id].spec);
  const inp = path.join(tmp, id + '.json'), o = inp + '.out', e = inp + '.err';
  fs.writeFileSync(inp, JSON.stringify(d.payload));
  let r = null;
  try {
    execFileSync(path.join(ROOT, 'r-portable/bin/Rscript.exe'),
      [path.join(ROOT, 'r-scripts/nonrandom_permanova.R'), inp, o, e],
      { cwd: ROOT, stdio: 'ignore', timeout: 300000 });
    r = JSON.parse(fs.readFileSync(o, 'utf8'));
  } catch (ex) { console.log(id, 'R 失败'); continue; }
  const dg = r.diagnostics || [];
  if (dg.length) warned.push(id);
  console.log(
    id.padEnd(18), 'scheme=' + String(r.permutation.scheme).padEnd(10),
    'p_free=' + String(r.observed.p_free).padEnd(8),
    'p_con=' + String(r.observed.p_constrained).padEnd(8),
    'diag=' + dg.length, dg.length ? ' | ' + String(dg[0]).slice(0, 70) : ''
  );
}
console.log('\n触发提醒的模板：', warned.join(', ') || '（无）');

