// 生成一个「每批 1 Case + 1 Control」的退化设计工作簿，供真机验证引擎提醒
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { pathToFileURL } from 'node:url';

const ROOT = 'C:/Custom/CodeRepository/Demo/electron-egg';
const XLSX = await import(pathToFileURL(path.join(ROOT, 'frontend/node_modules/xlsx/xlsx.mjs')).href);
const io = await import(pathToFileURL(path.join(ROOT, 'frontend/src/utils/sheetIo.js')).href);
const spec = await import(pathToFileURL(path.join(ROOT, 'frontend/src/utils/nonrandomSheetSpec.js')).href);
const RSCRIPT = path.join(ROOT, 'r-portable/bin/Rscript.exe');

// 3 个批次 × 每批 (1 Case + 1 Control) = 6 样本
// group 与 strata 完全同构：批次差异拉到天量，看它还能不能显著（答案是不能，而原因不是"没效应"）
const species = ['Bacteroides', 'Prevotella', 'Faecalibacterium', 'Ruminococcus', 'Akkermansia', 'Bifidobacterium'];
const rows = [], meta = [], coord = [];
const profiles = {
  Case: [[82, 6, 61, 9, 31, 4], [78, 9, 58, 12, 28, 6], [86, 5, 64, 7, 33, 3]],
  Control: [[6, 79, 9, 58, 5, 32], [9, 84, 7, 62, 4, 35], [5, 76, 11, 55, 6, 30]]
};
let k = 0;
for (let b = 1; b <= 3; b++) {
  for (const g of ['Case', 'Control']) {
    rows.push(profiles[g][b - 1]);
    meta.push([`S${++k}`, g, `B${b}`]);
    coord.push([`S${k}`, Number((b * 10 + (g === 'Case' ? 0.5 : 6.5)).toFixed(1)), Number((g === 'Case' ? 1 : 8).toFixed(1))]);
  }
}

const sheets = [
  ['物种矩阵', [['样本', ...species], ...rows.map((r, i) => [meta[i][0], ...r])]],
  ['样本信息', [['样本', 'group', 'strata'], ...meta]],
  ['坐标', [['样本', 'x', 'y'], ...coord.map(c => [c[0], c[1], c[2]])]],
  ['填写说明', [
    ['退化设计示例：每个批次只有 1 个 Case + 1 个 Control'],
    [''],
    ['这个文件是用来验证引擎提醒的，不是给人照着填的。'],
    ['受限置换只能在批次内部交换 group 标签。每批只有 1:1 时，'],
    ['把标签对调得到的置换与观测设计算出完全相同的 F，零分布退化，'],
    ['p 被并列比例钉死（本例约 0.27），组间差异拉到天量也不会显著。'],
    [''],
    ['预期现象：'],
    ['  1) 观测 F 很大（几十到几千），但 p（受限置换）远大于 0.05；'],
    ['  2) 结果区出现红框「受限置换的零分布退化…」，并给出三条出路；'],
    ['  3) 把 strata 那列改成每批 2 Case + 2 Control（共 12 样本），同样的数据就能显著。'],
    [''],
    ['表名支持中文：物种矩阵 / 样本信息 / 坐标。样本顺序随意，导入时按样本 ID 对齐。']
  ]]
];

// 1) 写出文件到 Downloads（先看目标文件是否存在，存在则备份）
const dl = 'C:/Users/uf107146/Downloads';
const target = path.join(dl, 'Non-random-PERMANOVA 退化示例_1Case1Control.xlsx');
const existing = path.join(dl, 'Non-random-PERMANOVA 数据模板_2026-11-18-06-12-54.xlsx');
if (fs.existsSync(existing)) console.log('（保留你下载的那份原文件，另存新文件）');

const wb = XLSX.utils.book_new();
for (const [n, aoa] of sheets) XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(aoa), n);
const bytes = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
fs.writeFileSync(target, Buffer.from(bytes));
console.log('已写出:', target, fs.statSync(target).size, '字节');

// 2) 走真实链路验一遍：readWorkbook -> mapWorkbook -> nrToFormPatch -> 引擎
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'degenxlsx-'));
const readSheets = await io.readWorkbook(new File([fs.readFileSync(target)], 'degen.xlsx'));
const mapped = io.mapWorkbook(readSheets, spec.NR_IMPORT_SHEETS, { primary: 'community' });
if (!mapped.ok) { console.log('导入被拒:', mapped.error); process.exit(1); }
const patch = spec.nrToFormPatch(mapped.fields);
const payload = {
  communityData: JSON.parse(patch.communityStr),
  sampleData: JSON.parse(patch.sampleStr),
  coordinates: patch.coordinatesStr ? JSON.parse(patch.coordinatesStr) : null,
  formula: 'group', scheme: 'stratified', strata: 'strata', distance: 'bray',
  permutations: 999, seed: 7
};
const inp = path.join(tmp, 'in.json'), o = inp + '.out', e = inp + '.err';
fs.writeFileSync(inp, JSON.stringify(payload));
execFileSync(RSCRIPT, [path.join(ROOT, 'r-scripts/nonrandom_permanova.R'), inp, o, e], { cwd: ROOT, stdio: 'ignore', timeout: 300000 });
const r = JSON.parse(fs.readFileSync(o, 'utf8'));
console.log('导入样本:', mapped.ids.join(','));
console.log('F =', r.observed.F_model.toFixed(1), '| p_free =', r.observed.p_free, '| p_constrained =', r.observed.p_constrained);
console.log('diagnostics 条数 =', (r.diagnostics || []).length);
(r.diagnostics || []).forEach(d => console.log('  提醒:', d));

