# ---------------- 公式项的合法性 ----------------
# 实机报回来的结果是 Df=8 / R²=1.0000 / F 与 p 全是 N/A：
# 签名指向“把样本 ID 当了解释变量”（9 个样本 9 个水平 = 逐字完美拟合）。
# 旧代码丱完全不管：adonis2 照跑，输出照样 success，前端把 N/A 端给用户看。
id_col <- colnames(sample_data)[1]
used_terms <- formula_terms_of(formula_str)
for (tt in used_terms) {
  if (identical(tt, id_col)) {
    stop(sprintf(paste0("公式里的 %s 是样本 ID 列（第一列），不能当解释变量：",           # tt / id_col
                        "每个样本一个水平，模型会“完美拟合”（R²=1），",           
                        "而 F 与 p 根本没有定义。请把公式改成分组列（如 Group）。"), tt))
  }
  if (!(tt %in% colnames(sample_data))) {
    stop(sprintf(paste0("公式里的 %s 不在样本表里。可用列：",                       # tt
                        paste(colnames(sample_data)[-1], collapse = ", "),
                        "（第一列 %s 是样本 ID，不参与建模）"), tt, id_col))
  }
  lev <- length(unique(sample_data[[tt]]))
  if (lev >= nrow(sample_data)) {
    stop(sprintf(paste0("公式里的 %s 有 %d 个不同取值，样本一共 %d 个 —— ",            # tt, lev, nrow
                        "每个样本自己一组，组内没有重复，PERMANOVA 无法 Partition 变异。",    
                        "分组列的层数应明显少于样本数。"), tt, lev, nrow(sample_data)))
  }
}

