  console.log(('['+label+'] 成功').padEnd(26),'F='+(j.F?+j.F.toFixed(3):'无'),'p='+(j.p_value!==undefined?j.p_value:'无'),'R²='+(+j.R2).toFixed(4),
    '行='+j.permanova_result.map(r=>(r._row||'?')+':Df'+r.Df).join(' '),
    '提醒='+(j.diagnostics||[]).length,((j.diagnostics||[])[0]||'').slice(0,40));
};
go('ID列当公式','Sample');
go('三层整数','Group');
go('显式因子','as.factor(Group)');
go('不存在的列','Treatment');
go('趋势+连续','Group + pH',{Sample:S,Group:G,pH:PH});
go('两层文本','Group',{Sample:S,Group:['Case','Case','Case','Control','Control','Control','Case','Case','Case']});
"

